class Solution { fun maximumSubarraySum(nums:IntArray,k:Int):Long{val frequency=HashMap<Int,Int>();var sum=0L;var answer=0L;var left=0;for(right in nums.indices){sum+=nums[right];frequency[nums[right]]=(frequency[nums[right]]?:0)+1;if(right-left+1>k){val value=nums[left++];sum-=value;val count=frequency[value]!!-1;if(count==0)frequency.remove(value)else frequency[value]=count};if(right-left+1==k&&frequency.size==k)answer=maxOf(answer,sum)};return answer} }
